  let sum = 0, even = false;
  for (let i = num.length - 1; i >= 0; i--) {
    let d = num.charCodeAt(i) - 48;
    if (d < 0 || d > 9) return false;
    if (even) { d *= 2; if (d > 9) d -= 9; }
    sum += d; even = !even;
