for (const part of fmt.formatToParts(d)) parts[part.type] = part.value;

const map = {
  'yyyy': parts.year,
  'MM':   parts.month,
  'dd':   parts.day,
  'HH':   parts.hour === '24' ? '00' : parts.hour,
  'mm':   parts.minute,
  'ss':   parts.second,
  'SSS':  parts.fractionalSecond || '000',
