  { type: 'slack-token',       re: /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/g },
  { type: 'openai-api-key',    re: /\bsk-(proj-)?[A-Za-z0-9_-]{20,}\b/g },
  { type: 'stripe-key',        re: /\b(sk|pk|rk)_(test|live)_[A-Za-z0-9]{16,}\b/g },
